select public.sembrar_plantilla_ficha(
  'CIA',
  'Cisterna de agua 5,000 gal · riego con bombeo hidráulico PTO',
  'Sale de la OT 2897 (Transporte e Inversiones Sanmarc S.A.C., cotización N° 3581-2026 del 30/01/2026), que trae la cotización completa. La OT 2823 (Municipalidad Distrital de Paiján, mayo 2025) es el mismo producto «CISTERNA DE 5000 GALONES PARA TRANSPORTE DE AGUA», pero no trae cotización adjunta ni ficha: solo aporta el nombre y la verificación, y su lista fija de accesorios de la sección 6 (sin marcas) no se mezcló porque la 2897 sí dice qué se vendió. Cuerpo elíptico ASTM A36 de 4.5 mm con rompeolas, sobrechasis de 8 mm, tina antiderrame, baranda tubular y piso estriado; llenado, despacho y riego por gravedad, más funciones con equipo de bombeo hidráulico PTO (bomba Pedrollo 3" x 4" de 360 GPM, motor Permco, bomba hidráulica FZH/SE-85-116). La sección CAÑON REGADOR CONTRA INCENDIO se copia en el lugar donde la cotización la escribe (después de las pruebas técnicas); si un cliente no lo pide, se quita esa sección entera. Sin alternativas de espesor entre fuentes. Plazo de la OT 2897: 45 días hábiles; la 2823 decía 20 días calendario.',
  $j$[{"seccion":"ESPECIFICACIONES","etiqueta":"MARCA/ MODELO","detalle":"METAL WORK – RIEGO"},{"seccion":"ESPECIFICACIONES","etiqueta":"Peso Neto (Tara)","detalle":"3.9 TM (+/- 3 %)."},{"seccion":"ESTRUCTURA","etiqueta":"Cuerpo","detalle":"Sección ELIPTICA."},{"seccion":"ESTRUCTURA","etiqueta":null,"detalle":"Fabricado íntegramente en plancha de acero estructural ASTM A36. De 4.5mm,"},{"seccion":"ESTRUCTURA","etiqueta":null,"detalle":"Rompeolas debidamente espaciados."},{"seccion":"ESTRUCTURA","etiqueta":null,"detalle":"Soldadura semi-automático MIG/MAG."},{"seccion":"ESTRUCTURA","etiqueta":null,"detalle":"Sobrechasis en acero ASTM.8 mm"},{"seccion":"ESTRUCTURA","etiqueta":null,"detalle":"Tina antiderrame."},{"seccion":"ESTRUCTURA","etiqueta":null,"detalle":"Anclaje de amarre acero ASTM A36,pernos G8"},{"seccion":"ESTRUCTURA","etiqueta":null,"detalle":"Guardabarros metalicos"},{"seccion":"ESTRUCTURA","etiqueta":null,"detalle":"Baranda de seguridad tubular de 0.90 cm de altura y piso antideslizante en plancha estriada."},{"seccion":"SISTEMA DE CARGA Y DESCARGA","etiqueta":"FUNCIONES DE LLENADO POR GRAVEDAD","detalle":"La operación de carga (llenado), se realiza mediante un (01) ducto de llenado “entrada de hombre” (manhole) de 550 mm de diámetro que va anclado a la brida de la cisterna."},{"seccion":"SISTEMA DE CARGA Y DESCARGA","etiqueta":"DISPENSADO POR GRAVEDAD","detalle":"La operación de descarga (despacho), se realiza mediante una línea directa con una válvula y mariposas de 8”"},{"seccion":"SISTEMA DE CARGA Y DESCARGA","etiqueta":"RIEGO POR GRAVEDAD","detalle":"Mediante regadera de tubo de 3”, ubicada en la parte posterior de cisterna y accionado con válvula neumática operada desde la cabina."},{"seccion":"SISTEMA DE CARGA Y DESCARGA","etiqueta":null,"detalle":"FUNCIONES CON EQUIPO DE BOMBEO HIDRAULICO - PTO"},{"seccion":"SISTEMA DE CARGA Y DESCARGA","etiqueta":"AUTOLLENADO POR SUCCION","detalle":"Mediante línea de succión de 4” con manguera de 8 metros, equipada con válvula check, canastilla y acople cam locks"},{"seccion":"SISTEMA DE CARGA Y DESCARGA","etiqueta":"DISPENSADO A PRESION","detalle":"Mediante línea de descarga; 1\", 2\" y 3\" con válvula de despacho y acoples su posicionamiento posterior"},{"seccion":"SISTEMA DE CARGA Y DESCARGA","etiqueta":"RIEGO A PRESIÓN","detalle":"Alcance de 15 m aprox. Controlado mediante comando neumático operados desde la cabina. mediante (03) rociadores ubicados en la parte posterior."},{"seccion":"SISTEMA DE CARGA Y DESCARGA","etiqueta":null,"detalle":"EQUIPOS:"},{"seccion":"SISTEMA DE CARGA Y DESCARGA","etiqueta":"BOMBA DE AGUA","detalle":"Centrifuga, marca PEDROLLO de 3” x 4”. caudal de 360 GPM aprox."},{"seccion":"SISTEMA DE CARGA Y DESCARGA","etiqueta":"MOTOR HIDRUALICO","detalle":"Marca Permco, de 3/4” o 1”."},{"seccion":"SISTEMA DE CARGA Y DESCARGA","etiqueta":"BOMBA HIDRAULICA","detalle":"FZH/SE-85-116."},{"seccion":"SISTEMA DE CARGA Y DESCARGA","etiqueta":"TANQUE HIDRAULICA","detalle":"Presenta visor de nivel de aceite y sistema de filtrado de alto rendimiento."},{"seccion":"SISTEMA DE CARGA Y DESCARGA","etiqueta":"VALVULAS HIDRAULICAS","detalle":"Válvula reguladora"},{"seccion":"SISTEMA DE CARGA Y DESCARGA","etiqueta":"VALVULAS HIDRAULICAS","detalle":"Válvula divisora"},{"seccion":"SISTEMA DE CARGA Y DESCARGA","etiqueta":"VALVULAS HIDRAULICAS","detalle":"Kits conectores hidráulicos"},{"seccion":"ACABADO","etiqueta":null,"detalle":"Arenado industrial - GENERAL"},{"seccion":"ACABADO","etiqueta":null,"detalle":"2 capas de base epoxico"},{"seccion":"ACABADO","etiqueta":null,"detalle":"Recubrimiento gloss. color a convenir."},{"seccion":"PRUEBAS TECNICAS","etiqueta":null,"detalle":"Pruebas de Funcionamiento de las cisternas."},{"seccion":"PRUEBAS TECNICAS","etiqueta":null,"detalle":"Operación, Mantenimiento, Partes y Garantía."},{"seccion":"CAÑON REGADOR CONTRA INCENDIO","etiqueta":null,"detalle":"Piton automático regulable 2” inoxidable."},{"seccion":"CAÑON REGADOR CONTRA INC