select public.sembrar_plantilla_ficha(
  'COA',
  'Compactador de residuos sólidos 15 m³ · con alza contenedor',
  'Sale de la OT 2849 (Municipalidad Distrital de La Esperanza, cotización N° 3411-2025 del 18/07/2025), la única de la familia COMPACTADOR que trae ficha técnica. Carrocería montada sobre chasis, carga y descarga posterior, relación de compactación 3:1, sistema hidráulico Parker. La OT 2796 (Nova Autos, «Compactadora de residuos sólidos») no trae proforma ni ficha y no dice si lleva alza contenedor ni su capacidad, así que no se tomó como fuente. La ficha no describe el mecanismo del alza contenedor: solo aparece en el título de la cotización. No hay diferencias de espesores que anotar porque hay una sola fuente. Refuerzo (2.ª pasada): OT 2932 (Cotización N° 3680-2026, 31/08/2026, NOVA AUTOS S.A.C.) — Misma configuración (COA sobre chasis, caja 15 m³, alza contenedor, carga posterior, compactación 3 a 1, válvulas Parker, 2+2+1+2 cilindros); la ficha 2026 es más corta y cambia detalles: trae sección ALZA CONTENEDOR (pivoteo posterior en tubular de 3", 1000 kg, 2 cilindros doble efecto, mando secundario) que la plantilla no describe; tailgate de 1.5 m³ (vs 1.0), peso 5 900 kg (vs 5 500), estanque de 120 (vs 40 galones); espesores en ASTM A-36 4.5 mm piso/laterales/techo, riel y placa eyectora 5-6 mm A-36/A-550, estructura 4.5-8 mm, tailgate piso y cuchara 4.5-6 mm AR 450; luces 8 faros redondos 4" + 12 LED laterales; porta conos, porta tacos y caja porta extintor van «no incluye accesorio» (la plantilla los tiene como incluidos); mismos 18 pasos de verificación en otro orden; plazo 120 días hábiles.',
  $j$[{"seccion":"ESTRUCTURA – DIMENSIONES GENERALES","etiqueta":"Capacidad de carga del depósito posterior","detalle":"1.0M3"},{"seccion":"ESTRUCTURA – DIMENSIONES GENERALES","etiqueta":"Peso Total aprox.","detalle":"5 500 Kg."},{"seccion":"ESTRUCTURA – DIMENSIONES GENERALES","etiqueta":"Sistema de Carga y Descarga","detalle":"Posterior"},{"seccion":"ESTRUCTURA – DIMENSIONES GENERALES","etiqueta":"Relación de Compactación","detalle":"De 3 a 1"},{"seccion":"ESTRUCTURA – DIMENSIONES GENERALES","etiqueta":null,"detalle":"(*) Varía según el tipo de residuos a recolectar."},{"seccion":"APLICACIÓN DE NORMAS","etiqueta":"Iluminación","detalle":"Según Reglamento de Tránsito Vehicular"},{"seccion":"APLICACIÓN DE NORMAS","etiqueta":"Diseño y fabricación","detalle":"Manual de Aseguramiento de la Calidad MW."},{"seccion":"APLICACIÓN DE NORMAS","etiqueta":"Soldadura","detalle":"Proceso semiautomático MIG/MAG AWS D1.1"},{"seccion":"TOLVA TRASERA (TAILGATE)","etiqueta":null,"detalle":"Fabricada de chapa de acero alta tensión, con sus componentes soldados eléctricamente con soldadura apropiada, por cordón continuo donde necesario, para garantizar la estanqueidad y la resistencia."},{"seccion":"TOLVA TRASERA (TAILGATE)","etiqueta":null,"detalle":"En toda la parte inferior y vertical de contacto con la parte trasera de la caja de carga hay una junta de sellado de goma de perfil apropiado, de gran resistencia, que impide el derrame del líquido proveniente de la compactación de la basura."},{"seccion":"TOLVA TRASERA (TAILGATE)","etiqueta":null,"detalle":"Los principales materiales utilizados en su construcción son los siguientes:"},{"seccion":"TOLVA TRASERA (TAILGATE)","etiqueta":"Fondo de la tolva de carga","detalle":"5,00 mm AR 450"},{"seccion":"TOLVA TRASERA (TAILGATE)","etiqueta":"Pared inferior de la tolva de carga","detalle":"3/16” HSLA, GRADO 70"},{"seccion":"TOLVA TRASERA (TAILGATE)","etiqueta":"Guías de la placa compactadora","detalle":"1/4” HSLA, GRADO 70"},{"seccion":"TOLVA TRASERA (TAILGATE)","etiqueta":"Chapa de la placa transportadora (barrido)","detalle":"3/16” HSLA, GRADO 50"},{"seccion":"TOLVA TRASERA (TAILGATE)","etiqueta":"Chapa de la placa compactadora","detalle":"3/16” HSLA, GRADO 50"},{"seccion":"TOLVA TRASERA (TAILGATE)","etiqueta":"Liner de la placa compactadora","detalle":"1/8” SAE 1008"},{"seccion":"DEPÓSITO PRINCIPAL (CAJA)","etiqueta":null,"detalle":"Fabricada de chapa de acero, con sus componentes soldados eléctricamente con los mismos criterios que la tolva trasera."},{"seccion":"DEPÓSITO PRINCIPAL (CAJA)","etiqueta":null,"detalle":"Los principales materiales utilizados en su construcción son los siguientes:"},{"seccion":"DEPÓSITO PRINCIPAL (CAJA)","etiqueta":"Piso","detalle":"ASTM A-572"},{"seccion":"DEPÓSITO PRINCIPAL (CAJA)","etiqueta":"Rampa trasera del piso","detalle":"ASTM A-36"},{"seccion":"DEPÓSITO PRINCIPAL (CAJA)","etiqueta":"Liner sobre la rampa trasera","detalle":"AR 450"},{"seccion":"DEPÓSITO PRINCIPAL (CAJA)","etiqueta":"Laterales – parte trasera","detalle":"ASTM A-572"},{"seccion":"DEPÓSITO PRINCIPAL (CAJA)","etiqueta":"Laterales – parte frontal","detalle":"ASTM A-36"},{"seccion":"DEPÓSITO PRINCIPAL (CAJA)","etiqueta":"Techo","detalle":"ASTM A-36"},{"seccion":"COMPACTACIÓN","etiqueta":null,"detalle":"Sistema hidráulico con control de compactación SMART-PACK, que permite una mayor eficiencia de compactación."},{"seccion":"COMPACTACIÓN","etiqueta":null,"detalle":"Sistema compactación por 02 placas (transportadora y compactadora)."},{"seccion":"COMPACTACIÓN","etiqueta":null,"detalle":"El equipo tiene una relación de compactación de 3:1 con un peso promedio por metro cúbico de la basura compactada de 480 - 600kg/m3, basado en una basura suelta de 160 - 200kg/m3. Sin embargo, estos valores pueden variar dependiendo de las características de la basura que se colecta y de la capacidad del chasis portante."},{"seccion":"COMPACTACIÓN","etiqueta":null,"detalle":"El equipo está preparado para realizar el ciclo completo de compactación (2.2 m3) cada 20-22 segundos."},{"seccion":"SISTEMA DE DESCARGA","etiqueta":null,"detalle":"Por medio de la placa eyectora, accionado por un cilindro hidráulico telescópico de doble efecto, inclinado y fijado al piso de la caja, el cual sólo debe ser accionado luego de la apertura del Tailgate."},{"seccion":"SISTEMA DE DESCARGA","etiqueta":null,"detalle":"La caja recolectora y el panel eyector es una estructura en acero soldado, cóncava, formada de láminas y perfiles con diseño propio, de gran resistencia a las deformaciones y desgaste debido al esfuerzo en el trabajo de operación."},{"seccion":"SISTEMA DE DESCARGA","etiqueta":null,"detalle":"Las guías de la placa eyectora son distantes del piso y evitan el acumulo de la basura."},{"seccion":"SISTEMA DE DESCARGA","etiqueta":null,"detalle":"La apertura y cierre del Tailgate también se realizan por medio de cilindros hidráulicos. El tiempo de descarga es de 29 segundos (11 segundos para la abertura de la cola y 18 segundos para la eyección de la basura)."},{"seccion":"SISTEMA HIDRÁULICO","etiqueta":null,"detalle":"Tanque para el aceite hidráulico de 40 galones con accesorios en la marca Parker."},{"seccion":"SISTEMA HIDRÁULICO","etiqueta":null,"detalle":"Válvula secundaria doble, marca Parker, ubicada en el lateral de la puerta trasera de la parte superior, de accionamiento manual externo con palancas, con desbloqueo automático, permite la parada y reversión del ciclo en cualquier instante."},{"seccion":"SISTEMA HIDRÁULICO","etiqueta":null,"detalle":"Válvula doble, marca Parker, ubicada en la parte frontal izquierda, usada para regular la presión en los cilindros levantadores e tailgate y la presión de inyección (en la placa eyectora), accionada por medio de palancas."},{"seccion":"SISTEMA HIDRÁULICO","etiqueta":null,"detalle":"Dos cilindros hidráulicos, para accionamiento de la placa transportadora (barrido)."},{"seccion":"SISTEMA HIDRÁULICO","etiqueta":null,"detalle":"Dos cilindros hidráulicos, para accionamiento de la placa compactadora"},{"seccion":"SISTEMA HIDRÁULICO","etiqueta":null,"detalle":"Un cilindro telescópico, de doble efecto, para accionamiento de la placa eyectora."},{"seccion":"SISTEMA HIDRÁULICO","etiqueta":null,"detalle":"Dos cilindros hidráulicos de acción simple efecto para el levantamiento de la tolva trasera."},{"seccion":"SISTEMA HIDRÁULICO","etiqueta":null,"detalle":"Tuberías de acero trefilado sin costura, bicromatizadas, con mangueras y conexiones, marca Parker, para uso en alta presión, compatibles con las solicitaciones exigidas."},{"seccion":"SISTEMA HIDRÁULICO","etiqueta":null,"detalle":"Sistema de conexiones Seal-lock en las tuberías (tecnología de Parker), que elimina escape de aceite."},{"seccion":"SISTEMA HIDRÁULICO","etiqueta":null,"detalle":"Comandos resistentes, funcionales, fáciles de usar, sin holguras, de acción rápida y de forma que no exijan esfuerzo físico del operador."},{"seccion":"SISTEMA ELÉCTRICO","etiqueta":null,"detalle":"Todos los cables eléctricos vulcanizados y faros LED."},{"seccion":"SISTEMA ELÉCTRICO","etiqueta":null,"detalle":"02 focos LED de 2” en la parte superior frontal."},{"seccion":"SISTEMA ELÉCTRICO","etiqueta":null,"detalle":"04 focos LED de 2” laterales por lado."},{"seccion":"SISTEMA ELÉCTRICO","etiqueta":null,"detalle":"08 focos LED de 6” posteriores partes superiores."},{"seccion":"SISTEMA ELÉCTRICO","etiqueta":null,"detalle":"02 stop posterior, 02 piratas."},{"seccion":"SISTEMA ELÉCTRICO","etiqueta":null,"detalle":"01 circulina estroboscópica."},{"seccion":"PINTURA","etiqueta":null,"detalle":"Arenado industrial"},{"seccion":"PINTURA","etiqueta":null,"detalle":"02 capas de pintura epoxica, luego el:"},{"seccion":"PINTURA","etiqueta":null,"detalle":"Acabado en gloss."}]$j$::jsonb,
