-- 27 plantillas en 14 carrocerías.

-- =============================================================================
-- DOS AJUSTES SOBRE LO QUE YA HABÍA
-- -----------------------------------------------------------------------------
-- La tolva genérica (TOLVA_VOLQUETE) conserva como predeterminada la ficha de
-- la migración 024 —una tolva montada de la casa— y no el remolque con tiro,
-- que es la excepción. Y la plataforma de la 024 (COT 3659, que es la OT 2925)
-- queda de baja: la reforzada de arriba la contiene como fuente y tenerlas las
-- dos era ofrecer la misma ficha con dos nombres.
-- =============================================================================
update public.plantillas_ficha p set predeterminada = false
  from public.tipos_carroceria t
 where t.id = p.tipo_carroceria_id and t.codigo = 'TOLVA_VOLQUETE' and p.nombre <> 'Tolva volquete estándar';
update public.plantillas_ficha p set predeterminada = true
  from public.tipos_carroceria t
 where t.id = p.tipo_carroceria_id and t.codigo = 'TOLVA_VOLQUETE' and p.nombre = 'Tolva volquete estándar';
update public.plantillas_ficha set activa = false, predeterminada = false
 where nombre = 'Plataforma semirremolque con suspensión neumática';
